// Strings
// For the #WCCChallenge << Connect the dots >> (join the discord! https://discord.gg/S8c7qcjw2b)

// This sketch is inspired by string art, drawing randomly some shapes then using the negative space
// around them using "strings" to draw the outlines. This used the amazing js-clipper library
// (https://sourceforge.net/projects/jsclipper/) to simplify some polyhon operations to create the
// shapes, as well as to detect line collisions


let cw, ch
let borderSep, numStrings, numPoints, numShapes, pointSize, mainCanvas

let palettes = [
  ['#ef233c', '#d5f2e3', '#73ba9b', '#003e1f', '#d90429'],
  ['#353535', '#3c6e71', '#ffffff', '#d9d9d9', '#284b63'],
  ['#ede0d4', '#e6ccb2', '#ddb892', '#b08968', '#7f5539'],
  ['#f0ead2', '#dde58f', '#adc178', '#a98467', '#6c584c'],
  ['#1c1515', '#700c0c', '#5a0303', '#615f5f', '#66707a'],
  ['#05668d', '#028090', '#00a896', '#02c39a', '#f0f3bd'],
  ['#3e92cc', '#2a628f', '#13293d', '#16324f', '#18435a'],
  ["#05668D", "#028090", "#00A896", "#02C39A", "#F0F3BD"],
]
let palette, bgColor, texture, shadowColor
let theStrings, thePoints, theGrid

function setup () {
  cw = windowWidth
  ch = windowHeight
  mainCanvas = createCanvas(cw, ch)
  angleMode(DEGREES)
  pixelDensity(1)
  regenerate()
}

function mouseClicked () {
  regenerate()
}

function draw () {
  background(bgColor)
  push()
  scale(0.9)
  translate(cw * 0.05, ch * 0.05)
  if (!theStrings) return
  updateStrings(theStrings)
  drawStrings(theStrings)
  drawPoints(...thePoints)
  pop()
  image(texture, 0, 0, cw, ch)
}

let regenerate = () => {
	let seed = floor(random(1000000))
  palette = random(palettes)
  bgColor = lerpColor(color(random(palette)), color('#EEE'), random(0.5, 0.9))
  shadowColor = lerpColor(color(random(palette)), color('#00000030'), random(0.5, 0.9))
  randomSeed(seed)

  if (random() < 0.7) {
    strokeCap(SQUARE)
  } else {
    strokeCap(ROUND)
  }

  numPoints = floor(random(15, 50))
  borderSep = max(40, min(cw, ch) / numPoints)
  numShapes = floor(random(15, 30))
  numStrings = floor(random(4, 7))
  pointSize = random(5, 12)
  theGrid = new Grid(cw + 1, ch + 1, borderSep) // Add +1 since we're putting points on the border

  let shapes
  if (random() < 0.5) {
    shapes = _getRandomSquares(numShapes)
  } else {
    shapes = _getTriangleShapes(numShapes / 2)
  }

  let shapePolygons = _getShapePolygons(shapes)
  let borderPoints = _getBorderPoints()
  let shapePoints = _getShapePoints(shapePolygons).flat()
  for (let p of borderPoints) { theGrid.insert(p) }
  for (let p of shapePoints) { theGrid.insert(p) }

  let borderStrings = _getBorderStrings(borderPoints, shapePolygons, shapePoints)
  let strings = _getStrings(borderPoints, borderStrings, shapePoints, shapePolygons)
  thePoints = [borderPoints, shapePoints]
  theStrings = strings

  texture = granulate(100)
}

let _getStrings = (borderPoints, borderStrings, shapePoints, shapePolygons) => {
  let strings = []
  let diagMaxLength = dist(0, 0, cw, ch)
  for (let k = 1; k < numStrings; k++) {
    for (let i = 0; i < borderStrings.length; i++) {
      let sp = borderStrings[i]
      let string = sp.strings[k]
      let li = lineIntersection(string.beam, shapePolygons)
      let ps = ClipperLib.Clipper.OpenPathsFromPolyTree(li)
      for (let l of ps) {
        let a = getClosestPoints(l[0])
        let b = getClosestPoints(l[1])
        if (!a || !b) {
          // Sometimes the clipping makes it so the points returned are way offscreen
          // console.error('No closest point found', l)
          continue
        }
        // Don't draw if the lines are the same, or are colinear
        if (a.X === b.X || a.Y === b.Y) {
          continue
        }
        let len = dist(a.X, a.Y, b.X, b.Y)
        let maxRange = map(len, 0, diagMaxLength, 10, 6, true)
        strings.push({
          a, b,
          color: random(palette),
          sw: random(3, 6),
          len,
          maxRange,
          range: 0,
          // range: maxRange,
          n: 0,
          angle: atan2(b.Y - a.Y, b.X - a.X),
          midPoint: {
            X: (a.X + b.X) / 2,
            Y: (a.Y + b.Y) / 2
          },
          up: true,
          speed: map(len, 0, diagMaxLength, 6, 2, true),
          vibrate: map(len, 0, diagMaxLength, 0.5, 0.2, true)
        })
      }
    }
  }
  return strings
}

let updateStrings = (strings) => {
  for (let s of strings) {
    if (mouseIsClose(s, 20) && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) !== (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) !== (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) {
      s.range = s.maxRange
    }
    if (s.range <= 0) {
      s.range = 0
      s.n = 0
      continue
    }
    if (s.up) {
      s.n += s.speed
      if (s.n >= s.range) {
        s.up = false
      }
    } else {
      s.n -= s.speed
      if (s.n <= -s.range) {
        s.up = true
      }
    }
    s.range -= s.vibrate
  }
}

// Determine if mouse is close to a string
// Taken from https://stackoverflow.com/a/6853926
let mouseIsClose = (string, threshold) => {
  let x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))
  let y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))
  // Transform mouse coords to the transformed coords (canvas is scaled and translated)
  x = (x - cw * 0.05) / 0.9
  y = (y - ch * 0.05) / 0.9
  let x1 = string.a.X
  let y1 = string.a.Y
  let x2 = string.b.X
  let y2 = string.b.Y

  var A = x - x1
  var B = y - y1
  var C = x2 - x1
  var D = y2 - y1

  var dot = A * C + B * D
  var len_sq = C * C + D * D
  var param = -1
  if (len_sq != 0) //in case of 0 length line
      param = dot / len_sq

  var xx, yy

  if (param < 0) {
    xx = x1
    yy = y1
  }
  else if (param > 1) {
    xx = x2
    yy = y2
  }
  else {
    xx = x1 + param * C
    yy = y1 + param * D
  }

  var dx = x - xx
  var dy = y - yy
  let d = Math.sqrt(dx * dx + dy * dy)
  return d < threshold
}

let drawStrings = (strings) => {
  noFill()
  for (let s of strings) {
    strokeWeight(s.sw)
    if (s.range <= 0) {
      stroke(shadowColor)
      line(s.a.X + 3, s.a.Y + 3, s.b.X + 3, s.b.Y + 3)
      stroke(s.color)
      line(s.a.X, s.a.Y, s.b.X, s.b.Y)
    } else {
      stroke(shadowColor)
      drawStrum(s, 0)
      stroke(s.color)
      drawStrum(s, 3)
    }
  }
}

let drawStrum = (s, delta) => {
  beginShape()
  vertex(s.a.X + delta, s.a.Y + delta)
  curveVertex(s.a.X + delta, s.a.Y + delta)
  let midPoint = s.midPoint
  let offset = s.n
  let x = midPoint.X + offset * cos(s.angle + 90)
  let y = midPoint.Y + offset * sin(s.angle + 90)
  curveVertex(x + delta, y + delta)
  curveVertex(s.b.X + delta, s.b.Y + delta)
  vertex(s.b.X + delta, s.b.Y + delta)
  endShape()
}

let drawPoints = (borderPoints, shapePoints) => {
  if (random() < 0.7) {
    for (let p of borderPoints) {
      noStroke()
      fill(random(palette))
      if (p.stringCount) {
        circle(p.X, p.Y, pointSize)
      }
    }

    for (let p of shapePoints) {
        noStroke()
        fill(random(palette))
        if (p.stringCount) {
          circle(p.X, p.Y, pointSize)
        }
    }
  }
}

let lerpLine = (x1, y1, x2, y2, t) => {
  return {
    X: lerp(x1, x2, t),
    Y: lerp(y1, y2, t)
  }
}

let _getTriangleShapes = (numShapes) => {
  let shapes = []
  for (let i = 0; i < numShapes; i++) {
    let q = floor(random(4))
    let points = []
    for (let k = 0; k < 4; k++) {
      if (q !== k) {
        switch(k) {
          case 0:
            points.push({ X: random(cw/2), Y: random(ch/2) })
            break
          case 1:
            points.push({ X: random(cw/2, cw), Y: random(ch/2) })
            break
          case 2:
            points.push({ X: random(cw/2, cw), Y: random(ch/2, ch) })
            break
          case 3:
            points.push({ X: random(cw/2), Y: random(ch/2, ch) })
            break
        }
      }
    }
    shapes.push(points)
  }
  return shapes
}

let _getRandomSquares = (numShapes) => {
  let shapes = []
  let maxSize = min(cw, ch)
  let j = random(cw / 20, cw / 10)
  for (let i = 0; i < numShapes; i++) {
    let points = []
    let size = random(maxSize / 6, maxSize / 3)
    let x = random(cw - j - size)
    let y = random(ch - j - size)
    points = [
      { X: x, Y: y },
      { X: x + size, Y: y },
      { X: x + size, Y: y + size },
      { X: x, Y: y + size },
    ].map(p => {
      return {
        X: constrain(p.X + random(-j, j), 0, cw),
        Y: constrain(p.Y + random(-j, j), 0, ch),
      }
    })
    shapes.push(points)
  }
  return shapes
}

let _getBorderPoints = () => {
  let borderPoints = []
  for (let x = 0; x < cw; x += borderSep) { borderPoints.push({ X: x, Y: 0 }) }
  for (let y = 0; y < ch; y += borderSep) { borderPoints.push({ X: cw, Y: y }) }
  for (let x = 0; x < cw; x += borderSep) { borderPoints.push({ X: cw - x, Y: ch }) }
  for (let y = 0; y < ch; y += borderSep) { borderPoints.push({ X: 0, Y: ch - y }) }
  return borderPoints
}

let _getShapePolygons = (shapes) => {
  let sources = shapes.slice(0, Math.floor(shapes.length / 3))
  let targets = shapes.slice(Math.floor(shapes.length / 3))
  let solution = new ClipperLib.Paths()
  let clipper = new ClipperLib.Clipper()
  clipper.AddPaths(sources, ClipperLib.PolyType.ptSubject, true)
  clipper.AddPaths(targets, ClipperLib.PolyType.ptClip, true)
  clipper.Execute(
    ClipperLib.ClipType.ctIntersection,
    solution,
    ClipperLib.PolyFillType.pftNonZero,
    ClipperLib.PolyFillType.pftNonZero,
  )
  let sol = solution
  solution = ClipperLib.JS.Clean(sol, 0.001 * cw)

  // Filter out shapes with small perimeter
  solution = solution.filter(s => {
    let perimeter = ClipperLib.JS.PerimeterOfPath(s)
    return perimeter > borderSep * 3
  })
  return solution
}

let _getShapePoints = (shapePolygons) => {
  let shapePoints = []
  for (let p of shapePolygons) {
    let points = []
    for (let i = 0; i < p.length; i++) {
      let x1 = p[i].X
      let y1 = p[i].Y
      let x2 = p[(i + 1) % p.length].X
      let y2 = p[(i + 1) % p.length].Y
      let d = dist(x1, y1, x2, y2)
      let numSegments = d / borderSep // Don't floor to use more points although not well distributed
      // let numSegments = round(d / borderSep)
      for (let j = 0; j < numSegments; j++) {
        points.push(lerpLine(x1, y1, x2, y2, j / numSegments))
      }
    }
    shapePoints.push(points)
  }
  return shapePoints
}

let _getBorderStrings = (borderPoints, shapePolygons, shapePoints) => {
  let diagMaxLength = dist(0, 0, cw, ch)
  let borderStrings = []
  for (let i = 0; i < borderPoints.length; i++) {
    let bp = borderPoints[i]

    let n1 = borderPoints[(i + 1) % borderPoints.length]
    let n0 = borderPoints[(i - 1 + borderPoints.length) % borderPoints.length]
    // Calculate the angle between the points
    let a1 = atan2(n1.Y - bp.Y, n1.X - bp.X)
    let a0 = atan2(n0.Y - bp.Y, n0.X - bp.X)
    let a = (a1 - a0)
    // If the angle is > 180, invert the second angle (so it is inside the canvas)
    if (a > 0) { a1 -= 360 }
    let numAngles = numStrings + 1
    let angleStep = (a1 - a0) / numAngles
    let angles = []
    let delta = random(-angleStep * 0.3, angleStep * 0.3)
    for (let j = 1; j < numAngles; j++) {
      angles.push(a0 + j * angleStep + delta)
    }
    // For each angle, draw a line of length diagMaxLength and calculate the intersections
    let strings = angles.map(a => {
      return {
        angle: a,
        beam: [
          bp,
          {
            X: bp.X + diagMaxLength * cos(a),
            Y: bp.Y + diagMaxLength * sin(a)
          }
        ],
        connected: false
      }
    })

    borderStrings.push({
      point: bp,
      strings: shuffle(strings)
    })
  }
  return borderStrings
}

let getClosestPoints = (point) => {
  let neighbors = theGrid.getNeighborhood(point, borderSep * 2)
  let minDist = Infinity
  let closest = null
  for (let p of neighbors) {
    let d = dist(p.X, p.Y, point.X, point.Y)
    if (d < minDist) {
      minDist = d
      closest = p
    }
  }
  return closest
}

let lineIntersection = (points, shapes) => {
  let c = new ClipperLib.Clipper()
  let solution = new ClipperLib.PolyTree()
  let margin = cw * 2
  // Add a thick "border" around the canvas to clip the lines
  let extendedBorder = [
    [{ X: -margin, Y: 0 }, { X: cw + margin, Y: 0 }, { X: cw + margin, Y: -margin }, { X: -margin, Y: -margin }],
    [{ X: -margin, Y: ch }, { X: -margin, Y: ch + margin }, { X: cw + margin, Y: ch + margin }, { X: cw + margin, Y: ch }],
    [{ X: 0, Y: 0 }, { X: -margin, Y: 0 }, { X: -margin, Y: ch }, { X: 0, Y: ch }],
    [{ X: cw, Y: 0 }, { X: cw + margin, Y: 0 }, { X: cw + margin, Y: ch }, { X: cw, Y: ch }],
  ]

  c.AddPath(points, ClipperLib.PolyType.ptSubject, false)
  c.AddPaths(extendedBorder, ClipperLib.PolyType.ptClip, true)
  c.AddPaths(shapes, ClipperLib.PolyType.ptClip, true)
  c.Execute(ClipperLib.ClipType.ctDifference, solution)
  return solution
}

function granulate(gA) {
  let gc = createGraphics(cw, ch)
  gc.loadPixels()
  let d = gc.pixelDensity()
  let halfImage = 4 * (cw * d) * (ch * d)
	// noprotect
  for (let ii = 0; ii < halfImage; ii += 4) {
    let x = (ii / 4) % (cw * d)
    let y = floor((ii / 4) / (cw * d))
    grainAmount = random(-gA, gA)
    gc.pixels[ii] = gc.pixels[ii] + grainAmount
    gc.pixels[ii + 1] = gc.pixels[ii + 1] + grainAmount
    gc.pixels[ii + 2] = gc.pixels[ii + 2] + grainAmount
    gc.pixels[ii + 3] = map(noise(x * 0.005, y * 0.005), 0, 1, 40, 60)
  }
  gc.updatePixels()
  return gc
}
